(function () {
  var st = document.createElement('style');
  st.textContent = "@font-face{font-family:'Galmuri9';src:url(data:font/woff2;base64,) format('woff2');font-display:block}\n@font-face{font-family:'Galmuri7';src:url(data:font/woff2;base64,) format('woff2');font-display:block}\n@font-face{font-family:'Galmuri11';src:url(data:font/woff2;base64,) format('woff2');font-display:block}\n@font-face{font-family:'Galmuri11B';src:url(data:font/woff2;base64,) format('woff2');font-display:block}";
  (document.head || document.documentElement).appendChild(st);
  var fs = ['10px Galmuri9', '8px Galmuri7', '12px Galmuri11', '12px Galmuri11B'];
  window.FONTS_READY = Promise.all(fs.map(function (f) { return document.fonts.load(f, '가나다ABC'); })).catch(function () {});
})();
